using System;

public class Program
{
    public static void Main()
    {
        int temp = int.Parse(Console.ReadLine());
        int humidity = int.Parse(Console.ReadLine());
        if (temp < 10)
            Console.WriteLine("البس جاكيت");
        else if (temp <= 25 && humidity > 70)
            Console.WriteLine("الجو رطب – لا تنسَ شرب الماء");
        else if (temp > 30 && humidity < 40)
            Console.WriteLine("الجو جاف – البس قبعة واحمل معك ماء");
        else if (temp > 35 && humidity > 60)
            Console.WriteLine("تحذير من موجة حر – تجنّب التعرض للشمس");
        else
            Console.WriteLine("الطقس معتدل – استمتع بيومك");
    }
}

